function zip(arr1, arr2) {
  const length = Math.min(arr1.length, arr2.length);
  const result = [];
  for (let i = 0; i < length; i++) {
    result.push([arr1[i], arr2[i]]);
  }
  return result;
}

console.log(zip(['小明', '小華'], [20, 25]));

