function IO(thunk) { return { run: thunk }; }

let callCount = 0;
function* apiCallStream() {
  while (true) {
    callCount += 1;
    const currentCall = callCount;
    yield IO(() => `第 ${currentCall} 次呼叫的結果`);
  }
}

function take(gen, n) {
  const results = [];
  for (let i = 0; i < n; i++) {
    results.push(gen.next().value.run());
  }
  return results;
}

console.log(take(apiCallStream(), 3));
console.log('總共建立了幾個 IO 動作（callCount）：', callCount);

